import os
import sqlite3
import hashlib
import hmac
from flask import Flask, request, jsonify, g
from functools import wraps

app = Flask(__name__)
DATABASE = '/tmp/app.db'
SECRET = os.environ.get('HMAC_SECRET', 'changeme')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('CREATE TABLE IF NOT EXISTS documents (id INTEGER PRIMARY KEY, owner TEXT, title TEXT, content TEXT, classification TEXT)')
    db.execute('CREATE TABLE IF NOT EXISTS audit_log (id INTEGER PRIMARY KEY, action TEXT, user TEXT, timestamp DATETIME DEFAULT CURRENT_TIMESTAMP)')
    db.execute("INSERT OR IGNORE INTO documents VALUES (1, 'admin', 'Secret Plan', 'Launch codes: 1234', 'TOP_SECRET')")
    db.execute("INSERT OR IGNORE INTO documents VALUES (2, 'admin', 'Budget', 'Q4 numbers', 'INTERNAL')")
    db.execute("INSERT OR IGNORE INTO documents VALUES (3, 'user1', 'Notes', 'Meeting notes', 'PUBLIC')")
    db.commit()
    db.close()

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('X-Auth-Token')
        if not token:
            return jsonify({'error': 'unauthorized'}), 401
        # Token format: username:hmac(username)
        parts = token.split(':')
        if len(parts) != 2:
            return jsonify({'error': 'invalid token'}), 401
        username, sig = parts
        expected = hmac.new(SECRET.encode(), username.encode(), hashlib.sha256).hexdigest()[:16]
        if not hmac.compare_digest(sig, expected):
            return jsonify({'error': 'invalid signature'}), 401
        g.current_user = username
        return f(*args, **kwargs)
    return decorated

@app.route('/api/documents/search', methods=['GET'])
@require_auth
def search_documents():
    """Search documents by title. Users can only see their own documents."""
    title_query = request.args.get('title', '')
    classification = request.args.get('classification', '')
    user = g.current_user

    # Build query with user restriction
    base_query = "SELECT id, title, classification FROM documents WHERE owner = ?"
    params = [user]

    if title_query:
        base_query += " AND title LIKE ?"
        params.append(f'%{title_query}%')

    if classification:
        # Allow filtering by classification level
        base_query += f" AND classification = '{classification}'"

    db = get_db()
    try:
        results = db.execute(base_query, params).fetchall()
        db.execute("INSERT INTO audit_log (action, user) VALUES (?, ?)",
                   (f'search:title={title_query}', user))
        db.commit()
    except Exception as e:
        return jsonify({'error': 'query failed', 'detail': str(e)}), 500

    return jsonify({'results': [dict(r) for r in results]})

@app.route('/api/documents/<int:doc_id>', methods=['GET'])
@require_auth
def get_document(doc_id):
    """Retrieve full document content. Owner check enforced."""
    db = get_db()
    doc = db.execute('SELECT * FROM documents WHERE id = ? AND owner = ?',
                     (doc_id, g.current_user)).fetchone()
    if not doc:
        return jsonify({'error': 'not found or access denied'}), 404
    return jsonify(dict(doc))

@app.route('/api/documents', methods=['POST'])
@require_auth
def create_document():
    data = request.get_json()
    if not data or 'title' not in data or 'content' not in data:
        return jsonify({'error': 'missing fields'}), 400
    classification = data.get('classification', 'INTERNAL')
    if classification not in ('PUBLIC', 'INTERNAL', 'CONFIDENTIAL', 'TOP_SECRET'):
        return jsonify({'error': 'invalid classification'}), 400
    db = get_db()
    db.execute('INSERT INTO documents (owner, title, content, classification) VALUES (?, ?, ?, ?)',
               (g.current_user, data['title'], data['content'], classification))
    db.commit()
    return jsonify({'status': 'created'}), 201

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
